  'Selectie opheffen': 'Скасувати вибір',
  'Ik ga akkoord met de EUPL 1.2-licentie en heb gelezen welke gegevens OciDeck bewaart.':
      'Я приймаю ліцензію EUPL 1.2 і ознайомився з тим, які дані зберігає OciDeck.',
  'Lees de volledige licentie': 'Прочитати повний текст ліцензії',
  'OciDeck is vrije software onder de EUPL 1.2-licentie. Voordat je begint, vragen we je de licentie te accepteren. Hieronder lees je ook welke gegevens OciDeck op dit apparaat bewaart en wanneer er iets je apparaat verlaat.':
      'OciDeck — це вільне програмне забезпечення за ліцензією EUPL 1.2. Перш ніж почати, ми просимо вас прийняти ліцензію. Нижче ви також можете прочитати, які дані OciDeck зберігає на цьому пристрої та коли щось залишає ваш пристрій.',
  'OciDeck verzamelt geen statistieken en stuurt uit zichzelf niets naar buiten. Standaard blijft alles op dit apparaat. Gegevens verlaten dit apparaat alleen als jij dat kiest:\n\n•  Nextcloud/WebDAV: verbind je met een server, dan worden je inlognaam en wachtwoord bewaard (het wachtwoord veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die server verstuurd.\n•  Openen via URL: OciDeck haalt het bestand op van het adres dat je invoert.\n•  Online media (staat standaard uit): indien ingeschakeld laadt OciDeck afbeeldingen en video\'s van de adressen in je dia\'s.\n•  Externe links (zoals de online licentie) openen in je browser.':
      'OciDeck не збирає статистику й нічого не надсилає самостійно. За замовчуванням усе залишається на цьому пристрої. Дані залишають цей пристрій лише за вашим вибором:\n\n•  Nextcloud/WebDAV: коли ви підключаєтеся до сервера, ваше ім’я користувача та пароль зберігаються (пароль надійно у сховищі ключів вашої системи), а презентації, які ви відкриваєте чи зберігаєте, надсилаються на цей сервер.\n•  Відкриття через URL: OciDeck отримує файл за введеною вами адресою.\n•  Онлайн-медіа (за замовчуванням вимкнено): якщо ввімкнено, OciDeck завантажує зображення й відео за адресами у ваших слайдах.\n•  Зовнішні посилання (як-от онлайн-ліцензія) відкриваються у вашому браузері.',
  'OciDeck wordt geleverd onder de European Union Public Licence v1.2. Door akkoord te gaan aanvaard je deze licentie. Je mag OciDeck gebruiken, kopiëren, aanpassen en verspreiden onder de voorwaarden van de EUPL 1.2.':
      'OciDeck надається за ліцензією European Union Public Licence v1.2. Погоджуючись, ви приймаєте цю ліцензію. Ви можете використовувати, копіювати, змінювати та поширювати OciDeck на умовах EUPL 1.2.',
  'Om te werken en je werk niet te verliezen, bewaart OciDeck gegevens lokaal op dit apparaat:\n\n•  Je instellingen en voorkeuren (taal, mappen, stijl- en weergaveprofielen, recente bestanden).\n•  Je presentatiematerialen: de presentaties die je opslaat, automatische herstelkopieën en bijlagen zoals afbeeldingsbeschrijvingen.\n•  Deze toestemmingskeuze.\n\nJe kunt dit verwijderen door de bestanden te wissen of de instellingen te resetten.':
      'Щоб працювати й не втратити вашу роботу, OciDeck зберігає дані локально на цьому пристрої:\n\n•  Ваші налаштування та вподобання (мова, теки, профілі стилю й вигляду, нещодавні файли).\n•  Ваші матеріали презентацій: презентації, які ви зберігаєте, автоматичні резервні копії відновлення та вкладення, як-от описи зображень.\n•  Цей вибір згоди.\n\nВи можете видалити це, стерши файли або скинувши налаштування.',
  'Volledige licentie online (23 officiële taalversies)':
      'Повний текст ліцензії онлайн (23 офіційні мовні версії)',
  'Wat OciDeck op dit apparaat bewaart':
      'Що OciDeck зберігає на цьому пристрої',
