  'Leeskolom': 'Колонка читання',
  'Ware grootte': 'Справжній розмір',
  'Pagina-einden gelden alleen op paginabreedte.':
      'Розриви сторінок діють лише за ширини сторінки.',
  'Hoe breed de leeskolom in de visuele modus is. Smal leest rustig, breed gebruikt meer van het scherm. Of je op die kolom, op paginabreedte of op het hele venster schrijft, kies je in de werkbalk.':
      'Наскільки широка колонка читання у візуальному режимі. Вузька читається спокійно, широка використовує більше екрана. Чи писати на цій колонці, на ширині сторінки чи на все вікно, ви обираєте на панелі інструментів.',
  'De sprong "{doel}" wijst naar een dia die niet meer bestaat; tijdens het presenteren gebeurt er niets. Kies een andere doeldia.':
      'Перехід «{doel}» указує на слайд, якого більше немає; під час презентації нічого не відбувається. Виберіть інший цільовий слайд.',
  'In een cirkel': 'Коло',
  'Onder elkaar': 'Список',
  'Categorie': 'Категорія',
  'Categorie toevoegen': 'Додати категорію',
  'Categorie opheffen (blokken blijven behouden)':
      'Прибрати категорію (блоки залишаються)',
  'Uitleg': 'Опис',
  'Een keuzemenu: elk blok springt bij aanklikken naar een andere dia. Typ per blok een label en een uitleg, kies de doeldia en eventueel een afbeelding. Kies de indeling: raster, onder elkaar of in een cirkel. Met categorieën wissel je tijdens het presenteren tussen groepen blokken. Een blok zonder doel is gewone tekst.':
      'Меню вибору: кожен блок під час натискання переходить до іншого слайда. Введіть підпис і опис для кожного блоку, виберіть цільовий слайд і за потреби зображення. Виберіть компонування: сітка, список або коло. За допомогою категорій під час презентації ви перемикаєтеся між групами блоків. Блок без цілі — це звичайний текст.',
  'Alleen een lege dia.': 'Лише порожній слайд.',
  'Hoofdstukken op nieuwe pagina': 'Розділи з нової сторінки',
  'Elk hoofdstuk begint nu op een nieuwe pagina':
      'Тепер кожен розділ починається з нової сторінки',
  'Elk hoofdstuk begon al op een nieuwe pagina':
      'Кожен розділ уже починався з нової сторінки',
  'Snijtekens': 'Мітки обрізу',
  'Alleen in de LaTeX/PDF-export, en alleen met afloop. Vereist het crop-pakket in je TeX-installatie; een browser-afdruk van de HTML-export zet ze niet.':
      'Лише в експорті LaTeX/PDF і лише з вилетом. Потребує пакет crop у вашій встановленій системі TeX; друк HTML-експорту з браузера їх не додає.',
  'Deze paginaopmaak staat in dit document':
      'Ці параметри сторінки збережені в цьому документі',
  'Deze paginaopmaak komt uit je instellingen':
      'Ці параметри сторінки взяті з ваших налаштувань',
  'Paginaopmaak': 'Параметри сторінки',
  'De paginamaat en marges staan nu in dit document; wie het opent krijgt dezelfde pagina. Haal ze eruit om je eigen instelling te laten gelden.':
      'Розмір сторінки та поля тепер збережені в цьому документі; кожен, хто його відкриє, отримає таку саму сторінку. Приберіть їх, щоб діяли ваші власні налаштування.',
  'De paginamaat en marges komen nu uit je instellingen, dus bij een ander kan het document anders uitvallen. Zet ze in het document om dat vast te leggen.':
      'Розмір сторінки та поля тепер беруться з ваших налаштувань, тож в іншої людини документ може виглядати інакше. Збережіть їх у документі, щоб це закріпити.',
