      'Стовпець сортування не містить чисел; найвищі/найнижчі та об\'єднання тоді не мають сенсу.',
  'Weergave beperken': 'Обмежити відображення',
  'Beperk het aantal getoonde items': 'Обмежити кількість показаних елементів',
