  'Toon hoeveel items verborgen zijn':
      'Показувати, скільки елементів приховано',
  'Toon alleen een deel van de bullets, tabel of grafiek. De oorspronkelijke data blijft in het bestand bewaard.':
      'Показувати лише частину пунктів, таблиці або діаграми. Початкові дані залишаються збереженими у файлі.',
  'Voor tabellen: kolomindex of naam om op te sorteren. Voor grafieken: naam van de reeks.':
      'Для таблиць: індекс або назва стовпця для сортування. Для діаграм: назва ряду.',
  'Online opslag is alleen beschikbaar in de desktopversie.':
      'Онлайн-сховище доступне лише в настільній версії.',
  'Online opslag': 'Онлайн-сховище',
  'Presentaties openen uit en opslaan naar WebDAV, S3 en git-repository’s, met versiebeheer en samenwerken via een forge. Een deel van deze paden is tot nu toe vooral tegen testomgevingen beproefd; kies dit bewust. Zonder de module werkt alles lokaal gewoon: mappen, bestanden en pakketten.':
      'Відкривай презентації з WebDAV, S3 і репозиторіїв git та зберігай їх туди, з контролем версій і співпрацею через forge. Частину цих шляхів досі випробувано переважно на тестових середовищах; вмикай це свідомо. Без модуля все локальне працює як звичайно: теки, файли та пакети.',
  'Er staan al online verbindingen ingesteld; die blijven werken, net als wachtend werk in de wachtrij. Uit betekent alleen: geen nieuwe online verbindingen toevoegen.':
      'Онлайн-з\'єднання вже налаштовані; вони працюють далі, як і робота, що чекає в черзі. Вимкнено означає лише: не додавати нових онлайн-з\'єднань.',
  'De module AI-assistentie staat uit, dus hier gebeurt niets. Zet hem aan bij Uitbreidingen. Wat je hieronder hebt ingesteld blijft staan.':
      'Модуль «Підтримка ШІ» вимкнено, тому тут нічого не відбувається. Увімкніть його в Розширеннях. Те, що ви налаштували нижче, зберігається.',
  'Hulp bij alt-teksten, beschrijvingen en formuleringen. Aanzetten verstuurt nog niets: dat gebeurt pas nadat je zelf een backend hebt gekozen en, bij een clouddienst, uitdrukkelijk hebt bevestigd. Een lokale backend verlaat je computer niet.':
      'Допомога з альтернативними текстами, описами та формулюваннями. Увімкнення поки нічого не надсилає: це станеться лише після того, як ви самі оберете бекенд і, у випадку хмарного сервісу, явно підтвердите. З локальним бекендом ніщо не покидає ваш комп\'ютер.',
  'Kies de backend op het tabblad AI-assistentie. Zolang daar niets staat, gebeurt er niets.':
      'Оберіть бекенд на вкладці «Підтримка ШІ». Поки там нічого не вибрано, нічого не відбувається.',
  'De voorbeelddia\'s van een sjabloon staan in het Engels. Naam en omschrijving volgen je eigen taal; de inhoud pas je na het aanmaken aan.':
      'Приклади слайдів у шаблоні — англійською. Назва й опис відповідають вашій мові; вміст ви зміните після створення.',
  'Meer': 'Більше',
  'Leesbaarheid van dit profiel': 'Розбірливість цього профілю',
  'Alle onderdelen halen de norm.': 'Усі елементи відповідають нормі.',
  'Deze verhoudingen gaan over de app zelf, niet over je dia\'s.':
      'Ці співвідношення стосуються самого застосунку, а не ваших слайдів.',
  'Tekst op kaarten en dialogen': 'Текст на картках і в діалогах',
  'Tekst op de schermachtergrond': 'Текст на тлі екрана',
  'Tekst en pictogrammen in de zijbalk': 'Текст і піктограми на бічній панелі',
  'Titel in de bovenbalk': 'Заголовок у верхній панелі',
  'Tekstknoppen en links': 'Текстові кнопки та посилання',
  'Selectievakjes, schakelaars en de tekstcursor':
      'Прапорці, перемикачі та текстовий курсор',
  'Het vinkje in een aangevinkt vakje': 'Позначка в увімкненому прапорці',
  'Label op de primaire knop': 'Напис на головній кнопці',
  'Bevindingen die je hebt beoordeeld en hebt laten staan. Ze worden niet meer gemeld, maar de scan blijft ze vinden en ze tellen niet als opgelost. Tik om er een terug te zetten.':
      'Виявлення, які ви переглянули й залишили. Про них більше не повідомляється, але сканування далі їх знаходить, і вони не вважаються усуненими. Торкніться, щоб повернути одне з них.',
  'Deze is beoordeeld en mag blijven': 'Перевірено, це може залишитися',
  'Mogelijk gemaakt door': 'Стало можливим завдяки',
  'De export is gestopt tijdens het voorbereiden.':
      'Експорт зупинився під час підготовки.',
  'Het bestand kon niet worden opgebouwd of weggeschreven. Controleer of er schijfruimte is en of de exportmap beschrijfbaar is.':
      'Не вдалося зібрати чи записати файл. Перевірте, чи є місце на диску та чи доступна тека експорту для запису.',
  'Het renderen van de dia\'s naar beeld is mislukt. Dit ligt aan een dia, niet aan het bestandsformaat: de HTML-export komt hier niet langs en werkt in dit geval meestal wel.':
      'Не вдалося відрендерити слайди в зображення. Причина — слайд, а не формат файлу: експорт у HTML сюди не заходить і в цьому випадку зазвичай працює.',
  'Technische melding:': 'Технічне повідомлення:',
  'presentaties': 'prezentatsii',
  '/Presentaties': '/Презентації',
  'De export is mislukt.': 'Експорт не вдався.',
  'Presenteer vanaf hier': 'Презентувати звідси',
  'Traffic Light Protocol: hoe breed mag dit materiaal gedeeld worden?':
