  'F-03 · SQL-injectie in het loginformulier':
      'F-03 · SQL-ін’єкція у формі входу',
  'https://app.voorbeeld/login': 'https://app.example/login',
  'Deze afbeelding naar het AI-model sturen?':
      'Надіслати це зображення до моделі ШІ?',
  'De afbeelding gaat ongewijzigd naar':
      'Зображення буде надіслано без змін до',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck нічого не редагує всередині зображення: обличчя, текст на знімку екрана та видимі дані надсилаються разом.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Перевірка зображень виявила тут одне або кілька впізнаваних облич.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Поряд з експортом створюються два файли, за якими одержувач може перевірити редагування.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'перелічує, що було вилучено, без самих значень. Цей файл можна надіслати разом зі звітом.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'містить ключі, за якими можна відновити кожне відредаговане значення. Не надсилайте цей файл: тоді редагування скасовується. Зберігайте його разом із джерелом.',
  'slides': 'слайди',
  'Achtergehouden': 'Приховано',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Приховано: класифіковано суворіше за презентацію',
  '1 slide achtergehouden door haar TLP': '1 слайд приховано через його TLP',
  'slides achtergehouden door hun TLP': 'слайдів приховано через їхній TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Ці слайди не потрапляють у показ, експорт чи пакет. Підвищте рівень TLP презентації у відомостях про презентацію, щоб їх включити.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Усі слайди приховано через їхню класифікацію TLP, тож немає чого показувати.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Усі слайди приховано через їхню класифікацію TLP, тож немає чого експортувати.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Усі слайди пропущено або приховано через їхню класифікацію TLP, тож немає чого показувати.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Усі слайди пропущено або приховано через їхню класифікацію TLP, тож немає чого експортувати.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Числа діаграм не збережено — вони залишилися лише в цьому вікні:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'У браузері немає відновлення після збою: якщо закрити цю вкладку, незбережена робота зникне. Збережіть презентацію самостійно.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Локальна база CVE (завантаження запускаєте ви самі): OciDeck отримує масив даних через api.github.com і файл випуску, на який вказує ця адреса.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Пошук CVE (типово вимкнено): якщо його ввімкнено, ваш пошуковий запит іде на налаштоване дзеркало CVE, а якщо там нічого не знайдено — до європейської бази ENISA та до MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Вбудоване відео з YouTube або Vimeo завантажує програвач із цієї служби.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  У браузері: якщо браузер відмовляється отримати адресу напряму, OciDeck пробує ще раз через сервер, з якого надійшов застосунок; тоді ця адреса потрапляє на той сервер.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Відкликання не збережено. Під час наступного запуску ваша згода діятиме знову.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Підзаголовок розділу, що оголошує нову частину презентації. Тримайте його коротким. Додайте фонове зображення з бібліотеки зображень.',
  'Bronnen doorzoeken…': 'Пошук у джерелах…',
  'Niet doorzocht': 'Не переглянуто',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Ця перевірка не працює у вебверсії: розпізнавання облич потребує системної бібліотеки, якої немає в браузері. Скористайтеся десктопною версією, щоб перевірити зображення на обличчя.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Токен потребує доступу на читання й запис до репозиторію. Gitea та Forgejo не мають пошуку на сервері; OciDeck шукає локально.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Токен потребує область repo (або деталізовано: Contents на читання й запис).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Токен потребує read_repository, write_repository та read_api. Пошук на сервері вимагає Advanced або Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Швидкий пошук на сервері — через затримку індексування щойно змінена колода може бути відсутня.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Медіа не зберігаються у звичайному файлі .md',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Зображення, відео та аудіо, вибрані на цій вкладці, існують лише в пам\'яті. Звичайний файл .md їх не збереже — після повторного відкриття їх не буде. Експортуйте як пакет .ocideck, щоб узяти медіа з собою.',
  'Media verwijderd om privacyredenen':
      'Медіа вилучено з міркувань конфіденційності',
  'Afbeeldingen door AI laten taggen?': 'Дозволити ШІ позначити ці зображення?',
