  'Cijfer verwijderen': 'Видалити показник',
  'Richting': 'Напрям',
  'ongewijzigd': 'без змін',
  'Lager is beter': 'Менше — краще',
  'Hoger is beter': 'Більше — краще',
  'Neutraal': 'Нейтрально',
  'Nu': 'Зараз',
  'Vorige rapportage': 'Попередній звіт',
  'Een scorecard toont hoogstens vijf cijfers; meer leest niet meer als een oordeel.':
      'Оцінна картка показує щонайбільше п\'ять показників; більше вже не читається як висновок.',
  'Laat de vorige rapportage leeg als er nog geen meting was; de slide toont dan geen verandering.':
      'Залиште попередній звіт порожнім, якщо вимірювання ще не було; слайд тоді не покаже зміни.',
  'Bepaalt of een stijging groen of rood kleurt. De pijl volgt altijd de cijfers.':
      'Визначає, чи буде зростання зеленим або червоним. Стрілка завжди слідує за числами.',
  'Een paar kerncijfers met het cijfer van de vorige rapportage ernaast, zodat de verandering het verhaal vertelt. Geef per cijfer aan of stijgen goed of slecht nieuws is.':
      'Кілька ключових показників із числом попереднього звіту поруч, щоб історію розповідала саме зміна. Для кожного вкажіть, чи зростання — це добра чи погана новина.',
  'Zekere vondsten als fout behandelen': 'Вважати певні знахідки помилками',
  'Normaal is een zekere vondst — een BSN, een IBAN, een e-mailadres — een waarschuwing die je kunt negeren. Aan maakt er een fout van, en dan kan de export erop blokkeren als je die instelling ook aan hebt staan. Bedoeld voor omgevingen waar zulke gegevens er echt niet doorheen mogen. Onzekere vondsten blijven een waarschuwing.':
      'Зазвичай певна знахідка — ідентифікаційний номер, IBAN, адреса електронної пошти — це попередження, яке можна проігнорувати. Увімкнено перетворює її на помилку, і тоді експорт може на ній заблокуватися, якщо те налаштування теж увімкнене. Призначено для середовищ, де такі дані справді не повинні проходити. Непевні знахідки залишаються попередженням.',
  'Medicare-nummer — een zorggegeven': 'номер Medicare — дані про здоров’я',
  'bedrijfsnummer': 'номер компанії',
  'zorgverzekeringsnummer (RAMQ) — een zorggegeven':
      'номер медичного страхування (RAMQ) — дані про здоров\'я',
  'zorgverzekeringsnummer (OHIP) — een zorggegeven':
      'номер медичного страхування (OHIP) — дані про здоров\'я',
  'bedrijfsnummer (BN)': 'номер підприємства (BN)',
  'zorgverlenersnummer (NPI)': 'номер медичного працівника (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'номер Medicare (MBI) — дані про здоров\'я',
  'wacht op verbinding': 'очікує з\'єднання',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Збережено на цьому комп\'ютері, ще не в репозиторії. Потрапить туди, щойно з\'явиться з\'єднання — або зараз, через «Очистити чергу».',
  'Branch (optioneel)': 'Гілка (необов\'язково)',
  'let op: de standaardbranch is': 'увага: гілка за замовчуванням —',
  'jij werkt op': 'ви працюєте на',
  'werkgeversnummer (EIN)': 'номер роботодавця (EIN)',
  'laatste vier cijfers van een SSN': 'останні чотири цифри SSN',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'дата народження, поштовий індекс і стать разом — ці три зазвичай вказують на одну особу, навіть без імені',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Сертифікат цього сервера не є довіреним. На власному сервера ви можете переглянути його та довіритися йому в Налаштування → Сховище.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Сертифікат цього forge не є довіреним. На власному forge ви можете переглянути його та довіритися йому в Налаштування → Сховище.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Сертифікат цього кінцевої точки не є довіреним. На власному кінцевої точки ви можете переглянути його та довіритися йому в Налаштування → Сховище.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Сертифікат forge не є довіреним — самопідписаний, прострочений або виданий на інше ім\'я.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
