  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'дані в нотатках доповідача — невидимі на слайді, але потрапляють в експорт',
  'Certificaat vertrouwen?': 'Довіряти цьому сертифікату?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Сертифікат цього сервера не підписаний визнаним видавцем. Для власного сервера це нормально, але так само виглядає й перехоплене з\'єднання.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Порівняйте відбиток нижче з тим, що показує ваш сервер. Якщо вони збігаються, ви спілкуєтеся з правильною машиною.',
  'Uitgegeven aan': 'Видано для',
  'Uitgegeven door': 'Ким видано',
  'Geldig tot': 'Дійсний до',
  'Vingerafdruk (SHA-256)': 'Відбиток (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Довіра стосується лише цього сертифіката. Якщо сервер його згодом замінить, OciDeck запитає знову.',
  'Vertrouwen': 'Довіряти',
  'Certificaat bekijken': 'Переглянути сертифікат',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Місця, де ти зберігаєш і шукаєш свої презентації — теки на цьому комп\'ютері, сервери WebDAV, бакети S3 і репозиторії git упереміш. Перетягни їх у потрібному порядку: найвищий свого роду вважається типовим.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Сховище S3: коли ти під\'єднуєшся до бакета, зберігаються кінцева точка, назва бакета і твій ключ доступу (таємний ключ безпечно у сховищі ключів твоєї системи), а презентації, які ти відкриваєш або зберігаєш, надсилаються до цієї служби зберігання.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Сховище Git: коли ти під\'єднуєшся до репозиторію, зберігається твій токен доступу (безпечно у сховищі ключів твоєї системи), а презентації, які ти зберігаєш, надсилаються на цей сервер як коміти. Робоча копія репозиторію залишається незашифрованою на цьому пристрої.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Для мови цієї презентації бракує назв хвороб. Релігію, політичні погляди та профспілкові терміни розпізнано, а шаблони з контрольною цифрою (ІПН, IBAN, паспорт) працюють завжди — але не розраховуйте на виявлення діагнозу.',
  'niet getest': 'не перевірено',
  'Werkte op': 'Працювало',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Ви увійшли, але не маєте тут доступу. Проблема не в паролі — попросіть адміністратора надати права на цю теку.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Ваш токен дійсний, але не має на це прав. Надайте йому більше прав або зачекайте, якщо форж застосовує обмеження.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Токен дійсний, але не має на це прав — надайте йому більше прав на репозиторій.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Ви увійшли, але доступу немає — проблема не в паролі. Попросіть права на цю теку.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Це схоже на повну DAV-адресу. Для Nextcloud OciDeck сам виводить цей шлях — тут має бути лише сервер.',
  'Overnemen': 'Застосувати',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV налаштовано неправильно — перевірте дані сервера в Налаштування → Сховище.',
