  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Цей форж має приватну або LAN-адресу. Позначте його як довірений внутрішній у Налаштування → Сховище.',
