  'Privacy blokkeert export': 'Приватність блокує експорт',
  'privacybevinding(en) zonder keuze':
      'виявлення персональних даних без ухваленого рішення',
  'Persoonsgegevens, bijzondere gegevens en geheimen in de tekst':
      'Персональні дані, особливі дані та секрети в тексті',
  'Slides, notities, tabellen, code, bestandspaden en URL\'s worden op dit apparaat doorzocht op identificerende nummers, financiële gegevens, contactgegevens, digitale identificatoren, geheimen, bijzondere persoonsgegevens (AVG art. 9/10), massagegevens en metadatalekken.':
      'Слайди, нотатки, таблиці, код, шляхи до файлів і URL перевіряються на цьому пристрої на ідентифікаційні номери, фінансові дані, контактні дані, цифрові ідентифікатори, секрети, особливі категорії персональних даних (GDPR ст. 9/10), масиви даних і витоки метаданих.',
  'Alleen een zekere treffer waarschuwt; waarschijnlijk en mogelijk blijven informatief. Een uitgezette regel vuurt nergens.':
      'Попереджає лише певний збіг; імовірний і можливий залишаються інформативними. Вимкнене правило ніде не спрацьовує.',
  'Niet gecontroleerd: persoonsgegevens, bijzondere gegevens en geheimen. De privacycontrole staat uit bij Beveiliging.':
      'Не перевірено: персональні дані, особливі дані та секрети. Перевірку приватності вимкнено в розділі «Безпека».',
  'Op deze slide': 'На цьому слайді',
  'Tijdens presenteren': 'Під час презентації',
  'Classificatie en privacy': 'Класифікація та приватність',
  'Logo tonen': 'Показувати логотип',
  'Footer tonen': 'Показувати нижній колонтитул',
  'Tabel bewerkbaar': 'Таблиця редагована',
  'Laat je de tabel tijdens het presenteren voor de zaal aanpassen. Staat standaard uit.':
      'Дозволяє змінювати таблицю перед аудиторією під час презентації. Типово вимкнено.',
  'Automatisch doorgaan': 'Переходити автоматично',
  'Persoonsgegevens': 'Персональні дані',
  'Wijzigen': 'Змінити',
  'Automatisch afspelen': 'Відтворювати автоматично',
  'Melden': 'Повідомляти',
  'Geaccepteerd': 'Прийнято',
  'Gewaarschuwd': 'З попередженням',
  'Weggelaten': 'Вилучено',
  'Bewerkbaar': 'Редаговане',
  'De privacycontrole': 'Перевірка приватності',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'OciDeck переглядає ваші слайди на предмет даних, які можуть бути чутливими: ідентифікаційні номери, контактні дані, номери телефонів, банківські рахунки, ключі та паролі, а також особливі категорії персональних даних. Усе відбувається на цьому пристрої: нічого не надсилається, і знайдене значення не з\'являється в жодному повідомленні.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'Перевірка не гарантує, що буде знайдено все; вона зменшує ймовірність ненавмисного витоку персональних даних.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'Текст на зображеннях залишається поза увагою, пов\'язані файли не відкриваються, а дані без розпізнаваного шаблону не розпізнає жоден сканер. Слайд без повідомлень — це слайд, на якому *ми* нічого не знайшли, а не слайд, про який доведено, що на ньому нічого немає. Те, чим ви ділитеся, залишається вашим рішенням і вашою відповідальністю.',
  'telefoonnummer': 'номер телефону',
  'Voor wie is deze export?': 'Для кого цей експорт?',
  'Volledig': 'Повний',
  'Geredigeerd': 'Відредаговано',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'Для замовника або аудитора: вилучається лише те, що ви позначили як «вилучити». Решта лишається читабельною, щоб третя сторона могла перевірити висновки.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'Для ширшого кола: вилучається все, що знаходить перевірка, зокрема на прийнятих слайдах. Файл отримує «-geredigeerd» у назві.',
  'tabel met persoonsgegevens (rijen×kolommen)':
      'таблиця персональних даних (рядки×стовпці)',
  'massa-persoonsgegevens op één slide':
      'масив персональних даних на одному слайді',
  'gebruikerspad met een naam erin': 'шлях користувача з іменем',
  'toegangstoken in een link': 'токен доступу в посиланні',
  'persoonsgegeven in een link': 'персональні дані в посиланні',
  'deellink met ingebakken toegang':
      'посилання для спільного доступу з вбудованим доступом',
  'e-mailadres in een link': 'адреса електронної пошти в посиланні',
  'ingesloten afbeelding — wij kunnen er niet in kijken':
      'вбудоване зображення — ми не можемо зазирнути всередину',
  'Je eigen gegevens': 'Ваші власні дані',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'По одному в рядку: ваше ім\'я, адреса електронної пошти, телефон або домен вашої організації. Те, що тут вказано, не повідомляється і не редагується — це відправник, а не виявлення. Домен (example.org) охоплює всі адреси під ним.',
  'Bij onafgehandelde persoonsgegevens':
      'За наявності неопрацьованих персональних даних',
  'Export afgebroken vanwege privacybevindingen.':
      'Експорт скасовано через виявлення персональних даних.',
  'Export blokkeren': 'Блокувати експорт',
  'Export geblokkeerd': 'Експорт заблоковано',
  'Export geblokkeerd: er staan persoonsgegevens in dit deck waarvoor nog geen keuze is gemaakt.':
      'Експорт заблоковано: у цій презентації є персональні дані, щодо яких ще не ухвалено рішення.',
  'Kies per slide wat er moet gebeuren, of exporteer bewust zoals het is.':
      'Оберіть для кожного слайда, що робити, або свідомо експортуйте як є.',
  'Maak per slide een keuze (accepteren, waarschuwen of weglaten) voordat je exporteert. Dit is zo ingesteld bij Beveiliging.':
      'Зробіть вибір для кожного слайда (прийняти, попередити або вилучити) перед експортом. Це налаштовано в розділі Безпека.',
  'Niets doen': 'Нічого не робити',
  'Persoonsgegevens in dit deck': 'Персональні дані в цій презентації',
  'Verder in dit deck:': 'Далі в цій презентації:',
  'Waarschuwen vóór export': 'Попереджати перед експортом',
